(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0018.js"] = [{"id":"glyph-seal-5ddd","script":"seal","character":"川","reading":"chuān","description":"chuān：(1)河流名山大～。～流不息。\n(2)平原，平地平～。米粮～。\n(3)特指中国四川省～剧。～菜。～贝。\n〔～资〕旅费。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-川"},{"id":"glyph-seal-5dde","script":"seal","character":"州","reading":"zhōu","description":"zhōu：(1)古代的一种行政区划，所辖地区的大小历代不同（后多用于地名）～县〖～。\n(2)中国一种民族自治行政区划海南省黎族苗族自治～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-州"},{"id":"glyph-seal-5de1","script":"seal","character":"巡","reading":"xún","description":"xún：(1)到各处去，来回走动查看～弋（指舰艇在海上巡逻）。～游。～天（指在天空巡游）。～回。～抚。～视。～幸（古代特指帝王出巡到达某地）。～逻。\n(2)酒席上给全座依次斟酒一遍～杯（主人在宴席上依次向客人劝酒）。酒过三～，菜过五味。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巡"},{"id":"glyph-seal-5de2","script":"seal","character":"巢","reading":"cháo","description":"cháo：(1)鸟搭的窝，亦指蜂、蚁等动物的窝；借指敌人或盗贼的藏身之所鸟～。蜂～。～窟。匪～。～穴。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巢"},{"id":"glyph-seal-5de5","script":"seal","character":"工","reading":"gōng","description":"gōng：(1)个人不占有生产资料，依靠工资收入为生的劳动者～人。～人阶级。～农联盟。\n(2)制造生产资料和生活资料的生产事业～业。～业革命。\n(3)从事体力或脑力劳动～作。～厂。竣～。\n(4)工作量记～。这个工程需要三十个～。\n(5)技术和技术修养唱～儿。～夫（ａ．本领，造诣，亦作功夫”；ｂ．时间）。～力。\n(6)细致，精巧～巧。～整。～笔（中国画技法，用笔工整，注重细部的描绘）。\n(7)善于，长于～书善画。～于心计。\n〔～尺（chě）〕中国古代一种记谱符号体系，有十个字合、四、一、上、尺、工、凡、六、五、乙，相当于简谱的５６７1234567。工”相当于3”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-工"},{"id":"glyph-seal-5de6","script":"seal","character":"左","reading":"zuǒ","description":"zuǒ：(1)面向南时，东的一边，与右”相对～手。～方。～右。～膀右臂。\n(2)地理上指东方山～。江～。\n(3)指政治思想上进步或超过现实条件许可的过头思想和行动～派。～翼。～倾。\n(4)斜，偏，差错～脾气。～嗓子。\n(5)降低官职～迁。\n(6)古同佐”，佐证。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-左"},{"id":"glyph-seal-5de7","script":"seal","character":"巧","reading":"qiǎo","description":"qiǎo：(1)技能好，灵敏～妙。～思。～劲。～干（gàn）。精～。轻～。乖～。心灵手～。～发奇中。\n(2)美好～笑（指美好的笑貌）。\n(3)虚伪（特指语言）～言。～诈。～辩。～言令色。\n(4)恰好～合。～遇。恰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巧"},{"id":"glyph-seal-5de8","script":"seal","character":"巨","reading":"jù；jv","description":"jù：(1)大，很大～大。～人（ａ．身材异常高的人；ｂ．童话里指比一般人高大，有神力的人；ｃ．喻有巨大影响和贡献的人）。～匠（泛称在科学或文艺上有极大成就的人）。～子（ａ．中国战国时墨家学派领袖的尊称；ｂ．在某方面卓有成就，有声望的人）。艰～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巨"},{"id":"glyph-seal-5de9","script":"seal","character":"巩","reading":"gǒng","description":"使坚固\n恐惧\n中国河南省县名","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巩"},{"id":"glyph-seal-5deb","script":"seal","character":"巫","reading":"wū","description":"wū：(1)以祈祷求神骗取财物的人～婆。女～。男～。～术。小～见大～（喻小的跟大的一比，就显得小不如大）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巫"},{"id":"glyph-seal-5dee","script":"seal","character":"差","reading":"chà；chā；chāi；cī","description":"chà：(1)错误话说～了。\n(2)不相当，不相合～不多。\n(3)缺欠还～十元钱。\n(4)不好，不够标准～等。成绩～。\n好；\nchā：(1)不同，不同之点～别。～距。～额。～价。\n(2)大致还可以～可。\n(3)错误～错。偏～。～池。\n(4)数学上指减法运算中的得数～数。四减二的～是二。\n好；\nchāi：(1)派遣去做事～遣。\n(2)旧时称被派遣的人～人。解～。\n(3)被派遣去做的事～事。公～。出～。\n好；\ncī：〔参（cēn）～〕见参3”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-差"},{"id":"glyph-seal-5df1","script":"seal","character":"己","reading":"jǐ","description":"jǐ：(1)对别人称本身自～。知～。反求诸～。推～及人。～所不欲，勿施于人。\n(2)天干的第六位，用作顺序第六的代称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-己"},{"id":"glyph-seal-5df3","script":"seal","character":"巳","reading":"sì","description":"sì：(1)地支的第六位，属蛇。\n(2)用于计时～时（上午九点至十一点）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巳"},{"id":"glyph-seal-5df4","script":"seal","character":"巴","reading":"bā","description":"bā：(1)粘结着的东西泥～。锅～。\n(2)粘贴，依附在别的东西上饭～锅了。～结别人。\n(3)贴近前不～村，后不～店。\n(4)盼，期望～望。\n(5)张开～着眼睛。\n(6)古国名，在今中国四川省东部。\n(7)中国四川省东部，泛指四川～蜀。～山蜀水。\n(8)词尾，读轻声尾～。嘴～。\n(9)大蛇～蛇（传说中能吞大象的蛇）。\n(10)气压的压强单位。\n(11)压强单位。\n(12)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巴"},{"id":"glyph-seal-5df7","script":"seal","character":"巷","reading":"xiàng；hàng","description":"xiàng：胡同，里弄小～。陋～。穷～。～陌（街道）。～战（在城市街巷里进行的战斗）。穷街陋～。\nhàng：义同（一）。\n〔～道〕采矿或探矿时挖的坑道。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巷"},{"id":"glyph-seal-5dfd","script":"seal","character":"巽","reading":"xùn","description":"xùn：(1)八卦之一，代表风。\n(2)古同逊”，谦让恭顺。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巽"},{"id":"glyph-seal-5dfe","script":"seal","character":"巾","reading":"jīn","description":"jīn：擦东西或包裹、覆盖东西的用品，多用纺织品制成手～。围～。领～。枕～。餐～。～帼（帼”是古代妇女的头巾，指妇女，如～～英雄”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-巾"},{"id":"glyph-seal-5e01","script":"seal","character":"币","reading":"bì","description":"泛指车马皮帛玉器等礼物\n币 bì货币人民～、金～、硬～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-币"},{"id":"glyph-seal-5e02","script":"seal","character":"市","reading":"shì","description":"shì：(1)做买卖或做买卖的地方开～。菜～。～井（街，市场）。～曹。～侩（旧指买卖的中间人、唯利是图的奸商；现泛指贪图私利的人）。\n(2)买～义。～恩（买好，讨好）。\n(3)人口密集的行政中心或工商业、文化发达的地方城～。都（dū）～。～镇。\n(4)一种行政区划，有中央直辖和省（自治区）辖等北京～。南京～。\n(5)中国人民习惯使用的度量衡单位～制。～尺。～斤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-市"},{"id":"glyph-seal-5e03","script":"seal","character":"布","reading":"bù","description":"bù：(1)棉、麻及棉型化学短纤维经纺纱后的织成物～匹。～帛。～衣。\n(2)古代的一种钱币。\n(3)宣告，对众陈述宣～。发～。～告。开诚～公（推诚相见，坦白无私）。\n(4)分散到各处散～。遍～。星罗棋～。\n(5)流传，散播～道。～施。\n(6)做出安排～置。～景。～局。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-布"},{"id":"glyph-seal-5e05","script":"seal","character":"帅","reading":"shuài","description":"军队中的主将、统帅\n⒈军队中最高级的指挥者元～。统～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帅"},{"id":"glyph-seal-5e08","script":"seal","character":"师","reading":"shī","description":"师今为隶属于军的单位,下辖若干旅或团\n泛指军队\n蹇叔之子与师,哭而送之曰晋人御师必于殽。”\n⒈指老师，导师教～。能者为～。～者，所以传道授业解惑也。〈引〉榜样～表。前事不忘，后事之～。\n⒉由师徒关系而产生的～叔。～弟。\n⒊效法，学习～其所长。\n⒋指擅长某种技术的人，又指技术职称医～。厨～。理发～。讲～。会计～。工程～。\n⒌军队出～。雄～百万。\n⒍军队的编制单位。一般是军的下一级，团的上一级。\n①学习的榜样。\n②培养师资的～范大学。\n⒑〈古〉称乐官乐～。\n①传授技艺的老师。\n②称呼有实践经验的工人老～傅。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-师"},{"id":"glyph-seal-5e0c","script":"seal","character":"希","reading":"xī","description":"xī：(1)少～少（shǎo）。～罕。～奇。～有。～世。\n(2)盼望～望。～冀。～图（心里盘算达到某种目的）。～求（ａ．希望得到；ｂ．希望和要求）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-希"},{"id":"glyph-seal-5e0f","script":"seal","character":"帏","reading":"wéi","description":"帐子;幔幕\n裙正面的一幅\n⒈帐子，幔幕。\n⒉〈古〉佩带的香囊。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帏"},{"id":"glyph-seal-5e10","script":"seal","character":"帐","reading":"zhàng","description":"⒈用布、纱、尼龙等做成的帷幕～幕。篷～。蚊～子。特指军用帷幕营～。攻入～中。\n⒉钱财出入的记载记～。现金日记～。\n⒊登记账目、户籍的本子或单子～簿。一本～。户籍～。一篇～单。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帐"},{"id":"glyph-seal-5e11","script":"seal","character":"帑","reading":"tǎng；nú","description":"tǎng：古代指收藏钱财的府库或钱财～藏（zàng）（指国库）。府～（府库里的钱财）。重（zhòng）～（大量的钱财）。\nnú：(1)古同孥”，儿女。\n(2)鸟尾鸟～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帑"},{"id":"glyph-seal-5e14","script":"seal","character":"帔","reading":"pèi","description":"pèi：古代披在肩背上的服饰凤冠霞～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帔"},{"id":"glyph-seal-5e16","script":"seal","character":"帖","reading":"tiē；tiè；tiě","description":"tiè：学习写字时摹仿的样本碑～。字～。画～。\ntiě：(1)便条字～儿。\n(2)邀请客人的纸片～子。请～。\n(3)写着生辰八字的纸片庚～。换～。\n(4)量词，用于配合起来的若干味汤药一～中药。\ntiē：(1)妥适妥～。安～。\n(2)顺从，驯服服～。俯首～耳。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帖"},{"id":"glyph-seal-5e18","script":"seal","character":"帘","reading":"lián","description":"旧时酒家、茶馆作店招的旗帜,用布做成\n帘子,遮蔽门窗的用具\n同奁”\n⒈用布、塑料、竹片、或苇子等做成遮蔽门窗的东西门～。窗～。\n⒉旧时商店门口做标志的旗帜茶～。酒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帘"},{"id":"glyph-seal-5e19","script":"seal","character":"帙","reading":"zhì","description":"zhì：(1)书、画的封套，用布帛制成。\n(2)整理书籍书乱谁能～，杯干自可添”。\n(3)量词，用于装套的线装书。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帙"},{"id":"glyph-seal-5e1a","script":"seal","character":"帚","reading":"zhǒu","description":"zhǒu：扫除尘土、垃圾的用具扫～。笤～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帚"},{"id":"glyph-seal-5e1b","script":"seal","character":"帛","reading":"bó","description":"bó：丝织品的总称布～。～书。～画。化干戈为玉～（喻变争斗为友善）。竹～（指书籍）。简蠹～裂（书坏了）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帛"},{"id":"glyph-seal-5e1c","script":"seal","character":"帜","reading":"zhì","description":"急挥帜。\n标记","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帜"},{"id":"glyph-seal-5e1d","script":"seal","character":"帝","reading":"dì","description":"dì：(1)宗教徒或神话中称宇宙的创造者和主宰者上～。玉皇大～。\n(2)君主～王。皇～。称～。～制。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帝"},{"id":"glyph-seal-5e26","script":"seal","character":"带","reading":"dài","description":"①带子或带状物鞋～、车～。\n②区域沿海一～。\n③携带～上一本书。\n④引导～路。\n⑤附带连说～笑。\n⑥含面～微笑。\n【带操】一种以带为器械的艺术体操项目。带子一般为绸缎，长度7米。基本动作有摆动、绕环、蛇形、螺形、抛接等。\n【带分数】〈数〉整数后面带着分数的数。\n【带余除法】〈数〉若a是任一整数，b是任一正整数，则必唯一存在整数q和r，使a=bq+r，其中0≤r≤b。这里，q叫做b除a的不完全商，简称商，r叫做余数。计算不完全商和\n余数的过程叫做带余除法。这个结论可推广到多项式上去。\n【带状纹样】见【二方连续纹样】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-带"},{"id":"glyph-seal-5e2d","script":"seal","character":"席","reading":"xí","description":"xí：(1)用草或苇子编成的成片的东西，古人用以坐、卧，现通常用来铺床或炕等～子。草～。苇～。竹～。凉～。～地而坐。～卷（juǎn）。\n(2)座位～位。～次。出～。列～。\n(3)酒筵，成桌的饭菜筵～。宴～。酒～。\n(4)特指议会中当选的人数四～。\n(5)职位主～。西～（塾师）。\n(6)量词一～酒。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-席"},{"id":"glyph-seal-5e37","script":"seal","character":"帷","reading":"wéi","description":"wéi：围在四周的帐幕～幕。～幔。～幄（军用的帐幕）。～子。～帐。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帷"},{"id":"glyph-seal-5e38","script":"seal","character":"常","reading":"cháng","description":"cháng：(1)长久，经久不变～数。～量（亦称恒量”）。～项。～任。～年。～驻。～住。～备不懈。\n(2)时时，不只一次～～。～客。时～。经～。\n(3)普通的，一般的～识。～务。～规。～情。～人。平～。反～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-常"},{"id":"glyph-seal-5e3b","script":"seal","character":"帻","reading":"zé","description":"犹冠。类似帽子的东西\n帻zé〈古〉一种头巾。\n帻cè 1.牙整齐而上下相切。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帻"},{"id":"glyph-seal-5e3c","script":"seal","character":"帼","reading":"guó","description":"古代妇女的头巾,头饰\n古代妇女的丧冠","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-帼"},{"id":"glyph-seal-5e45","script":"seal","character":"幅","reading":"fú","description":"fú：(1)布的宽度～面。双～。宽～。\n(2)泛指事物的宽度～度。～员（幅”是宽度，员”是周围。指疆域或领土的面积。如我国～～广大”）。振～。篇～。\n(3)边缘边～。\n(4)量词，用于布帛、图画等一～画。五～布。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幅"},{"id":"glyph-seal-5e54","script":"seal","character":"幔","reading":"màn","description":"màn：张在屋内的帐幕～帐。～子。布～。窗～。帷～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幔"},{"id":"glyph-seal-5e55","script":"seal","character":"幕","reading":"mù","description":"mù：(1)覆着在上面的帐帐～。夜～。～天席地。\n(2)垂挂在舞台前部的帷帐～布。～后。开～。银～。帷～。\n(3)古代战争期间将帅办公的地方～府。～宾。～僚。\n(4)戏剧较完整的段落，亦喻生活中的情景序～。独～剧。\n(5)古代作战时用的铁制臂甲和腿甲。\n(6)覆盖解朝服而～之”。\n(7)古同漠”，沙漠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幕"},{"id":"glyph-seal-5e5e","script":"seal","character":"幞","reading":"fú","description":"fú：同袱”。\n〔～头〕古代男子用的一种头巾。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幞"},{"id":"glyph-seal-5e61","script":"seal","character":"幡","reading":"fān","description":"fān：用竹竿等挑起来直着挂的长条形旗子。\n〔～然〕同翻然”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幡"},{"id":"glyph-seal-5e62","script":"seal","character":"幢","reading":"zhuàng；chuáng","description":"chuáng：(1)古代原指支撑帐幕、伞盖、旌旗的木竿，后借指帐幕、伞盖、旌旗。\n(2)刻着佛号或经咒的石柱经～。石～。\n〔～～〕形容影子摇晃，如人影～～”。\nzhuàng：量词，指房屋一～大楼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幢"},{"id":"glyph-seal-5e72","script":"seal","character":"干","reading":"gān；gàn","description":"gān：干燥；干预；牵涉；古代盾牌。gàn：做事；事物的主体部分，如干活、树干、骨干。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5e73","script":"seal","character":"平","reading":"píng","description":"píng：(1)不倾斜，无凹凸，像静止的水面一样～地。～面。～原。\n(2)均等～分。～行（xíng）。抱打不～。公～合理。\n(3)与别的东西高度相同，不相上下～列。～局。～辈。\n(4)安定、安静～安。～服。\n(5)治理，镇压～定。\n(6)抑止（怒气）他把气～了下去。\n(7)和好宋人及楚人～”。\n(8)一般的，普通的～民。～庸。～价。～凡。\n(9)往常，一向～生（ａ．从来；ｂ．终身）。～素。\n(10)汉语四声之一～声。～仄。\n(11)姓。\n(12)古同评”，评议。\n〔～假（jiǎ）名〕日本文所用的草书字母。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-平"},{"id":"glyph-seal-5e74","script":"seal","character":"年","reading":"nián","description":"nián：(1)地球绕太阳一周的时间一～。三～五载。\n(2)每年的～会。～鉴。～利。～薪。\n(3)一年的开始～节。新～。\n(4)有关年节的（用品）～画。～礼。～货。\n(5)时期，时代近～。～华。～号（ａ．帝王用的纪年名称；ｂ．公元纪年名称）。～限。～深日久。\n(6)收成～成。～景。～谨。荒～。\n(7)岁数～纪。～事（岁数）。～高。～轮。\n(8)人一生所经年岁的分期幼～。童～。青～。壮～。中～。老～。\n(9)科举时代同年考中者的互称～兄。～谊（同年登科的关系）。\n(10)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-年"},{"id":"glyph-seal-5e76","script":"seal","character":"并","reading":"bìng；bīng","description":"bìng：(1)合在一起～拢∠～。兼～。\n(2)一齐，平排着～驾齐驱。～重（zhòng）。～行（xíng）。\n(3)连词，表平列或进一层～且。\n(4)用在否定词前，加强否定的语气，表不像预料的那样～不容易。\nbīng：中国山西省太原市的别称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-并"},{"id":"glyph-seal-5e78","script":"seal","character":"幸","reading":"xìng","description":"xìng：(1)意外地得到成功或免去灾害～运。侥～。～存。～免。～未成灾。\n(2)福气～福。荣～。\n(3)高兴庆～。欣～。～甚。\n(4)希望～勿推却。～来告语之。\n(5)宠爱宠～。得～。\n(6)指封建帝王到达某地巡～。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幸"},{"id":"glyph-seal-5e7a","script":"seal","character":"幺","reading":"yāo","description":"yāo：(1)小，排行最末的～叔。～妹。\n(2)数目一（ａ．称呼电话号码等；ｂ．色子和骨牌中的一点）呼～喝（hè）六。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幺"},{"id":"glyph-seal-5e7b","script":"seal","character":"幻","reading":"huàn","description":"huàn：(1)空虚的，不真实的～想。～影。～境。～灭（受到现实的打击而消灭）。亦真亦～。虚～。梦～。\n(2)变化～化（奇异的变化）。变～莫测。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幻"},{"id":"glyph-seal-5e7c","script":"seal","character":"幼","reading":"yòu","description":"yòu：(1)年纪小，初出生的～儿。～虫。～苗。～年。\n(2)小孩儿～教（jiào）。～师。扶老携～。\n(3)对儿童爱护～吾幼，以及人之幼。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幼"},{"id":"glyph-seal-5e7d","script":"seal","character":"幽","reading":"yōu","description":"yōu：(1)隐藏，不公开的～会。～居（ａ．隐居；ｂ．幽静的住处）。～愤。～咽。\n(2)形容地方很僻静又光线暗～谷。～静。～暗。\n(3)沉静而安闲～闲。～趣（幽雅的趣味）。～婉。\n(4)把人关起来，不让跟外人接触～禁。～闭。～囚。\n(5)迷信的人指阴间～灵。～魂。\n(6)古地名，大致相当于今中国河北省、辽宁省南部一带～州。～燕（yān）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-幽"},{"id":"glyph-seal-5e7f","script":"seal","character":"广","reading":"guǎng；ān","description":"ān：同庵”，多用于人名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-广"},{"id":"glyph-seal-5e84","script":"seal","character":"庄","reading":"zhuāng","description":"谨严持重\n⒈严肃，端重～严。～重。亦～亦谐。\n⒉村子，田舍村～。山～。\n⒊封建社会里帝王贵族及地主占有的大片土地皇～。～园。祝家～。\n⒋某些商店的名称茶～。钱～。布～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庄"},{"id":"glyph-seal-5e86","script":"seal","character":"庆","reading":"qìng","description":"蜀遣卫尉陈震庆权践位。╠\n⒈棕～祝。～贺。～丰收。～功大会。\n⒉可棕的事佳～。国～。喜～。\n庆qiāng 1.发语词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庆"},{"id":"glyph-seal-5e87","script":"seal","character":"庇","reading":"bì","description":"bì：遮蔽，掩护～护。～短。包～。～荫（ａ．遮住阳光；ｂ．喻包庇袒护）。～佑（保佑）。～护权。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庇"},{"id":"glyph-seal-5e8a","script":"seal","character":"床","reading":"chuáng","description":"chuáng：(1)供人睡卧的家具～铺。木～。～榻。\n(2)像床的东西车～。机～∮～。\n(3)量词，用于被褥等两～被。\n(4)井上围栏后园凿井银作～，金瓶素绠汲寒浆”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-床"},{"id":"glyph-seal-5e8f","script":"seal","character":"序","reading":"xù","description":"xù：(1)次第顺～。秩～。次～。工～。程～。～数。\n(2)排列次第～次。～列。\n(3)开头的，在正式内容之前的～言。～跋。～曲。～幕。～论。\n(4)古代指送别赠言的文字。\n(5)指季节四～。\n(6)古代地方办的学校庠～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-序"},{"id":"glyph-seal-5e90","script":"seal","character":"庐","reading":"lú","description":"亦泛指简陋居室\n⒈简陋的房屋草～。\n⒉居住可～。\n⒊宾客住的宿舍十里有～，～有饮食。\n⒋庐山，在江西省。\n庐lǘ 1.古邑名。一作\"卢\"。在今湖北襄阳西南。本春秋庐戎国，被楚灭后为楚邑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庐"},{"id":"glyph-seal-5e91","script":"seal","character":"庑","reading":"wǔ","description":"泛指房屋\n屋檐\n⒈高堂下周围的廊房，厢房。\n⒉房屋～殿。大～。\n庑wú 1.草木茂盛。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庑"},{"id":"glyph-seal-5e93","script":"seal","character":"库","reading":"kù","description":"后泛指贮物的屋舍\n⒈贮藏东西的地方或建筑物仓～。书～。大水～。\n⒉电荷量单位\"库伦\"的简称，符号c。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-库"},{"id":"glyph-seal-5e94","script":"seal","character":"应","reading":"yīng；yìng","description":"yīng：应该，应当。yìng：回答，响应，适合，如答应、应对、适应。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5e95","script":"seal","character":"底","reading":"dǐ；de","description":"dǐ：(1)最下面的部分～层。～座。～下（ａ．下面；ｂ．以后）。～。～肥。\n(2)末了年～。月～。到～。\n(3)根基，基础，留作根据刨根问～。～蕴。～稿。～版。\n(4)图案的基层白～蓝花的瓶子。\n(5)何，什么～事伤感。\n(6)古同抵”，达到。\n顶；\nde：同的3”③。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-底"},{"id":"glyph-seal-5e96","script":"seal","character":"庖","reading":"páo","description":"páo：(1)厨房～厨。\n(2)厨师～人（厨师）。～丁。名～。～代（替人处理或担任事情。亦称代庖”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庖"},{"id":"glyph-seal-5e99","script":"seal","character":"庙","reading":"miào","description":"庙在\n⒉〈古〉朝廷、帝王处理政事的地方～堂。廊～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庙"},{"id":"glyph-seal-5e9a","script":"seal","character":"庚","reading":"gēng","description":"gēng：(1)天干的第七位，用作顺序第七的代称。\n(2)年龄同～。年～。生～（人出生的年月）。～帖（tiě）。～齿（年龄）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庚"},{"id":"glyph-seal-5e9c","script":"seal","character":"府","reading":"fǔ","description":"fǔ：(1)储藏文书或财物的地方～库。天～。\n(2)旧时封建贵族和官僚的主宅，泛指一般人的住宅～邸。～第。王～。～上。\n(3)中国唐代至清代的行政区域名，等级在县和省之间开封～。～尹。～治。～试。首～。\n(4)国家行政机关政～。官～。\n(5)古同腑”，脏腑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-府"},{"id":"glyph-seal-5e9e","script":"seal","character":"庞","reading":"páng","description":"脸盘\n多而杂乱的\n高大\n⒈大，高大～大。～然大物。\n⒉多而杂乱～杂。\n⒊脸盘面～。\n庞lóng 1.充实。参见\"庞庞\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庞"},{"id":"glyph-seal-5e9f","script":"seal","character":"废","reading":"fèi","description":"泛指倾圮,倒塌\n废弃;废除\n停止; 中\n⒈停止，放弃～止。～用。～除。作～。～寝忘食。切莫半途而～。〈引〉没有用的，失去功效的～物。～纸。～话连篇。变～为宝。\n⒉荒芜，衰败荒～。～屋。～墟。\n⒊残疾残～。无手足则肢体～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-废"},{"id":"glyph-seal-5ea0","script":"seal","character":"庠","reading":"xiáng","description":"xiáng：古代称学校～序（古代乡学，泛指学校）。～生。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庠"},{"id":"glyph-seal-5ea5","script":"seal","character":"庥","reading":"xiū","description":"xiū：(1)庇荫，保护～庇。～荫。\n(2)古同休”，止息。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庥"},{"id":"glyph-seal-5ea6","script":"seal","character":"度","reading":"dù；duó","description":"dù：(1)计算长短的器具或单位尺～。刻～。～量衡。\n(2)事物所达到的境界程～。高～。风～。\n(3)分角的单位，一圆周角分为360度角～。\n(4)依照计算的一定标准划分的单位温～。湿～。经～。纬～。浓～。\n(5)电能的单位，一千瓦小时电量的通称。\n(6)法则，应遵行的标准制～。法～。\n(7)哲学上指一定事物保持自己质的数量界限。\n(8)能容受的量气～。\n(9)考虑，打算置之～外。\n(10)过，由此到彼～日。～假。欢～新春。\n(11)量词，次一～。再～。\n(12)僧尼道士劝人出家剃～（剃发出家）。\n(13)姓。\nduó：计算，推测忖～。揣～。审时～势。～德量力。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-度"},{"id":"glyph-seal-5ead","script":"seal","character":"庭","reading":"tíng","description":"tíng：(1)堂阶前的院子～院。～园。～除（除”，台阶）。\n(2)厅堂～宇。～闱（父母所属内室，借指父母）。～训（父亲的教诲，亦指家教）。家～。\n(3)审判案件的处所或机构法～。\n(4)古同廷”，朝廷。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庭"},{"id":"glyph-seal-5eb6","script":"seal","character":"庶","reading":"shù","description":"shù：(1)众多～务。～物。～绩。富～。\n(2)平民，百姓～民。～人。黎～。\n(3)宗法制度下家庭的旁支，与嫡”相对～子（妾生的儿子）。～母（嫡出子女称父亲的妾）。～姓（古代称与帝王没有亲属关系的异姓诸侯）。\n(4)表示希望发生或出现某事，进行推测；但愿，或许～竭驽钝，攘除奸凶”。～免于难。～几（ａ．也许可以，表示希望；ｂ．近似，差不多；ｃ．旧指贤者）。～乎可行。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庶"},{"id":"glyph-seal-5eb7","script":"seal","character":"康","reading":"kāng","description":"kāng：(1)安宁～乐（lè）。～平。～宁。\n(2)空，空虚萝卜～了。\n(3)宽阔～庄。～衢（四通八达的大路）。\n(4)无病～健。～复。～泰。健～。\n(5)丰盛小～。～年。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-康"},{"id":"glyph-seal-5eb8","script":"seal","character":"庸","reading":"yōng","description":"yōng：(1)平常，不高明的平～。～医。～言。～俗。～人。昏～。～主（平庸或昏庸的君主）。～夫。～暗（平凡，愚昧）。～～碌碌（没有志气，没有作为）。\n(2)需要无～细述。无～讳言。\n(3)岂，怎么～讵（岂，何以，怎么，亦作庸遽”）。\n(4)中国唐代一种赋税法租～调。\n(5)功劳～绩（功绩）。\n(6)古同佣”，雇佣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庸"},{"id":"glyph-seal-5ebe","script":"seal","character":"庾","reading":"yǔ","description":"yǔ：(1)露天的谷仓～积。\n(2)古代容量单位，一庾等于十六斗。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-庾"},{"id":"glyph-seal-5ec9","script":"seal","character":"廉","reading":"lián","description":"lián：(1)堂屋的侧边～隅（棱角，喻品行端方，有气节）。\n(2)不贪污～洁。～正。～明。\n(3)便（pián）宜，价钱低物美价～。\n(4)察考，访查且～问，有不如吾诏者，以重论之”。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-廉"},{"id":"glyph-seal-5eca","script":"seal","character":"廊","reading":"láng","description":"láng：(1)房屋前檐伸出的部分，可避风雨，遮太阳～子。前～后厦。\n(2)庑下，殿下外屋～庑（堂前廊屋）。\n(3)有顶的过道长～。走～。画～。游～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-廊"},{"id":"glyph-seal-5ed6","script":"seal","character":"廖","reading":"liào","description":"liào：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-廖"},{"id":"glyph-seal-5edb","script":"seal","character":"廛","reading":"chán","description":"chán：(1)古代城市平民的房地～里（古代城市中住宅的通称）。市～（集市）。\n(2)古同缠”，束。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-廛"},{"id":"glyph-seal-5eea","script":"seal","character":"廪","reading":"lǐn","description":"lǐn：(1)米仓，亦指储藏的米仓～。～生（即廪膳生员”，中国明、清两代称由府、州、县按时发给银子和补助生活的生员）。～饩（旧指由官府供给的粮食）。\n(2)积聚，郁结～于肠胃”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-廪"},{"id":"glyph-seal-5ef6","script":"seal","character":"延","reading":"yán","description":"yán：(1)引长～长（cháng）。～续。蔓～。～年益寿。\n(2)展缓，推迟～迟。～缓。～宕。～误。\n(3)引进，请～聘（聘请）。～纳。～师。～医。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-延"},{"id":"glyph-seal-5ef7","script":"seal","character":"廷","reading":"tíng","description":"tíng：封建时代君主受朝问政的地方朝（cháo）～。宫～。～杖。～试（科举时代皇帝的殿试）。～对（ａ．在朝廷中当众对答；ｂ．科举时代皇帝的殿试）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-廷"},{"id":"glyph-seal-5efa","script":"seal","character":"建","reading":"jiàn","description":"jiàn：(1)立，设置，成立～立（ａ．开始成立；ｂ．开始产生，开始形成）。～树（建立功业，或所建立的功业）。～国。～都（dū）。～党。～军。～交。～设。～功立业。\n(2)造，筑～造。～筑。修～。新～。兴（xīng）～。筹～。\n(3)提出，倡议～议。～策（出谋献策）。\n(4)指中国福建省～兰。\n(5)北斗的斗柄所指的方位。斗柄农历每月所指的方位不同，因此建”亦转指月份（亦称月建”、月尽”）大～（农历有三十天的月份，亦称大尽”）。小～（农历有二十九天的月份，亦称小尽”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-建"},{"id":"glyph-seal-5eff","script":"seal","character":"廿","reading":"niàn","description":"niàn：二十～四史。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-廿"},{"id":"glyph-seal-5f00","script":"seal","character":"开","reading":"kāi","description":"打开,开启\n⒈跟\"关\"相对。把关着的东西打开～门。～窗。～锁。〈引〉\n①放散，张开百花盛～。笑逐颜～。～口讲话。\n②化整体为部分六十四～本。\n门、电键。\n⒉发掘，辟出，使显露出来～发。～辟。～煤矿。～荒山。～采黄金。\n⒊发动，发放，操纵～火车。～枪。～炮。～动机器。\n⒋起始～始。～头。～学。～春。\n⒍举行～会讨论。～学典礼。\n⒎揭示，表明～诚布公。～宗明义。\n⒏通，启发，使通～通。～导。～窍。～路先锋。\n⒐列举，列出～清单。计～。〈引〉逐个付出～支。～销。\n⒑清除，革除～除。\n⒒摆脱～脱。\n⒓沸，滚喝～水。汤～了。\n⒔分离，分配分～。离～。三七～。\n⒕写～处方。～收据。\n⒖扩大，发展～拓。～展。～源节流。\n⒗广阔，爽朗，乐观～阔。～朗。\n⒘用在动词后面，〈表〉效果走～。传～了。打～窗户。张～嘴巴。睁～眼睛。放～双手。\n⒙〈外〉黄金的纯度单位，二十四～为纯金。⒚热力学温度单位\"开尔文\"的简称，符号k。⒛","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-开"},{"id":"glyph-seal-5f02","script":"seal","character":"异","reading":"yì","description":"yì：(1)不同的～乎。～说。～常。～己（与自己意见不同或利害相冲突的人）。～端（旧时指不符合正统思想的主张或教义，如～～邪说”）。～化。～性。～样。大同小～。～曲同工。\n(2)分开离～。～居。\n(3)另外的，别的～日。～地。～国。～乡。～类。\n(4)特别的奇～。～闻。～彩。奇才～能（特殊的才能）。\n(5)奇怪惊～。诧～。怪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-异"},{"id":"glyph-seal-5f03","script":"seal","character":"弃","reading":"qì","description":"qì：舍去，扔掉抛～。遗～。～权。～市（古代在闹市执行死刑，并将尸体暴露街头）。～世（超出世俗或指去世）。～养（父母死亡的婉辞）。～置不顾。～瑕录用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弃"},{"id":"glyph-seal-5f04","script":"seal","character":"弄","reading":"nòng；lòng","description":"nòng：(1)玩耍，把玩摆～。玩～。～臣（帝王所亲近狎昵的臣子）。～潮儿。戏～。～瓦（瓦”是原始的纺锤，古代把它给女孩子玩，意为生女儿）。～璋（璋”是一种玉器，古代把它给男孩子玩。意为生儿子）。\n(2)做，干～假成真。～明白。\n(3)设法取得～点钱花。\n(4)搅扰这事～得人心惶惶。\n(5)耍，炫耀搔首～姿。\n(6)不正当地使用～权。～手段。捉～。\n(7)奏乐或乐曲的一段、一章～琴。梅花三～。\n(8)古代百戏乐舞中指扮演角色或表演节目。\nlòng：方言，小巷，胡同～堂。里～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弄"},{"id":"glyph-seal-5f08","script":"seal","character":"弈","reading":"yì","description":"yì：(1)古代称围棋～楸（棋盘）。\n(2)下棋对～。～林。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弈"},{"id":"glyph-seal-5f0b","script":"seal","character":"弋","reading":"yì","description":"yì：(1)用带绳子的箭射鸟～获。～人何篡（篡”，取，鸿雁飞得很高，射鸟的人无所施其技）。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弋"},{"id":"glyph-seal-5f0f","script":"seal","character":"式","reading":"shì","description":"shì：(1)物体外形的样子～样。样～。\n(2)特定的规格格～。程～。\n(3)典礼，有特定内容的仪式开幕～。阅兵～。\n(4)自然科学中表明某些关系或规律的一组符号分子～。算～。公～。\n(5)一种语法范畴，表示说话者对所说事情的主观态度叙述～。命令～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-式"},{"id":"glyph-seal-5f11","script":"seal","character":"弑","reading":"shì","description":"弑shì〈古〉指臣杀君，子杀父～君。～父。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弑"},{"id":"glyph-seal-5f13","script":"seal","character":"弓","reading":"gōng","description":"gōng：(1)射箭或发弹丸的器具～箭。～弩。飞鸟尽，良～藏。\n(2)像弓的器具或形态胡琴～子。～鞋。\n(3)旧时丈量地亩用的器具和计算单位。\n(4)弯曲～身。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弓"},{"id":"glyph-seal-5f15","script":"seal","character":"引","reading":"yǐn","description":"yǐn：(1)拉，伸～力。～颈。～而不发。～吭高歌。\n(2)领，招来～见。～子。～言。～导。～荐。抛砖～玉。\n(3)拿来做证据、凭据或理由～文。～用。援～。\n(4)退却～退。～避。\n(5)旧时长度单位，一引等于十丈。\n(6)古代柩车的绳索发～（出殡）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-引"},{"id":"glyph-seal-5f17","script":"seal","character":"弗","reading":"fú","description":"fú：不～去。～许。自愧～如。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弗"},{"id":"glyph-seal-5f18","script":"seal","character":"弘","reading":"hóng","description":"hóng：(1)大（现多用宏”）～愿。～图。～业。～谋。恢～（ａ．宽阔、广大，如气度～～”；ｂ．发扬，如～～士气”。亦作恢宏”）。\n(2)扩充，光大～扬。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弘"},{"id":"glyph-seal-5f1b","script":"seal","character":"弛","reading":"chí","description":"chí：(1)放松，松懈，解除松～。废～。～惰（懈怠）。～缓（局势、气氛等变和缓）。～张（张”，拉紧弓弦；弛”，放松弓弦，喻兴废、宽严、劳逸等）。\n(2)延缓～期。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弛"},{"id":"glyph-seal-5f1f","script":"seal","character":"弟","reading":"dì；tì；tuí","description":"dì：(1)同父母（或只同父、只同母）的比自己年纪小的男子～～。兄～。\n(2)亲戚或亲族间辈分相同的比自己年纪小的男子表～。堂～。\n(3)称同辈比自己年纪小的男性老～。师～。\n(4)学生对老师自称或别人指称～子。徒～。\n(5)古同第”，次序。\n(6)古同第”，但。\n兄；\ntì：古同悌”，孝悌。\n兄；\ntuí：〔～靡〕颓唐；柔顺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弟"},{"id":"glyph-seal-5f20","script":"seal","character":"张","reading":"zhāng","description":"开弓;拉弓弦\n⒈将弦安在弓上。〈引〉拉开弓～弓。\n⒉乐器上弦改弦更～。\n⒊开，展开～开。～口。大～旗鼓。纲举目～。\n⒋伸展，扩大，夸大伸～。扩～。夸～。虚～声势。\n⒌放纵，无拘束乖～。气焰嚣～。\n⒍陈设，铺排大～筵席。铺～浪费。\n⒎看，望东～西望。\n⒏指商店开业开～。\n⒐量词两～床。四～报纸。\n⒑星宿名。二十八宿之一。\n①惊慌～皇失措。\n②夸大，炫耀～皇其词。\n①设罗网捕虫鸟。\n②料理，筹划，应酬烦你～罗照应。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-张"},{"id":"glyph-seal-5f26","script":"seal","character":"弦","reading":"xián","description":"xián：(1)系在弓背两端的、能发箭的绳状物弓～。～韦（弦”指弓弦，韦”是兽皮，弦紧皮软，喻性子急缓不同。古人佩弦来警戒自己的性缓，佩韦以警戒自己的性急；后遂用弦韦”喻朋友的规劝）。～月（农历每月初七、八或二十二、三，月亮半圆，形似弓弦，故名）。上～（农历每月初七或初八的月相）。下～（农历每月二十二或二十三的月相）。应～而倒。\n(2)乐器上发声的线琴～。～子（ａ．指琴弦；ｂ．乐器三弦”的通称）。～歌。管～。续～（古人以琴瑟喻夫妻，故又以断弦”喻丧妻，以续弦”喻再娶）。～外之音。\n(3)中国古代称不等腰直三角形的斜边。\n(4)中医脉象名～脉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弦"},{"id":"glyph-seal-5f27","script":"seal","character":"弧","reading":"hú","description":"hú：(1)古代指木弓桑～。～矢。弦木为～。\n(2)圆周的任意一段～形。～线。～度。电～。～光。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弧"},{"id":"glyph-seal-5f29","script":"seal","character":"弩","reading":"nǔ","description":"nǔ：一种用机械力量射箭的弓，泛指弓～弓。～机。～手（弓手）。～箭。～炮（发射石块的弩机）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弩"},{"id":"glyph-seal-5f2d","script":"seal","character":"弭","reading":"mǐ","description":"mǐ：(1)平息，停止，消除～除。～谤（止息诽谤）。～患。～兵（平息战争）。\n(2)安抚，安定内～父兄，外抚诸侯。\n(3)顺服～从。\n(4)弓末的弯曲处。\n(5)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弭"},{"id":"glyph-seal-5f2f","script":"seal","character":"弯","reading":"wān","description":"折,使弯曲\n停船靠岸,停泊\n大爷吩咐急急收了口\n⒈屈曲，不直～曲。～腰。\n⒉曲折的部分～道。拐个～子。转左～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弯"},{"id":"glyph-seal-5f31","script":"seal","character":"弱","reading":"ruò","description":"ruò：(1)力气小，势力小，与强”相对～小。柔～。脆～。薄～。～不禁风。柔心～骨（形容人心地温柔，性格和顺）。\n(2)年纪小～冠（泛指男子二十岁左右的年纪）。\n(3)不够，差点儿，与强”相对三分之一～。\n(4)差，不如～于。～点。\n(5)丧失（指人死）又～了一个。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弱"},{"id":"glyph-seal-5f39","script":"seal","character":"弹","reading":"dàn","description":"形状像弹丸的东西,如圆形的果实;禽鸟的卵等\n弹弓\n炸弹\n①弹子；弹丸。\n②枪弹、炮弹、炸弹之类的总称。又见tán。\n【弹道导弹】'弹道式导弹'的简称。由火箭发动机推送到一定高度和一定速度后，发动机关闭，弹头沿着预定弹道飞向目标。\n【弹道曲线】炮弹飞行的轨迹。\n【弹道式导弹】见【弹道导弹】。\n【弹尽粮绝】见【弹尽援绝】。\n【弹尽援绝】弹药用尽，又得不到补给和救援。形容战事艰难，处境十分险恶。又作弹尽粮绝。\n【弹丸】\n①弹弓弹射所用的泥石小球或铁制小球。\n②比喻地方狭小～之地。\n⒈利用弹性射出弹丸等～击。\n⒉用手指拨弄，敲击。或手指受压后，用力伸出的动作～琴。～冠。～了他两下。\n⒊使振动～动。～棉花。\n⒋批评，抨击，检举评～。讥～。～劾。\n⒎［弹性］物体受外力后变形，外力一去即恢复原状的性能。〈引〉收缩性。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弹"},{"id":"glyph-seal-5f3a","script":"seal","character":"强","reading":"qiáng；qiǎng；jiàng","description":"qiáng：(1)健壮，有力，与弱”相对～壮。～健。～人。～力。～大。～劲。刚～。富～。列～。～弩之末。年富力～。\n(2)程度高～手。～烈。～酸。能力～。\n(3)胜过，优越，好～干。争～好（hào）胜。\n(4)有余，略多于某数～半（超过一半）。\n(5)使用强力，硬性地～占。～加。～攻。～悍。～横（hèng）。～梁（强横霸道）。\n(6)着重，增加分量～化。增～。\n弱；\nqiǎng：硬要，迫使，尽力～使。～迫。～逼。～辩。勉～。～人所难。～词夺理。\n弱；\njiàng：固执，强硬不屈～嘴。倔～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-强"},{"id":"glyph-seal-5f3c","script":"seal","character":"弼","reading":"bì","description":"bì：辅佐～士（辅佐的人）。～匡（辅佐匡正的人）。～导。～谐。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弼"},{"id":"glyph-seal-5f40","script":"seal","character":"彀","reading":"gòu","description":"gòu：(1)使劲张弓～中（弓箭射程所及的范围，喻圈套、牢笼）。入～。入我～中。\n(2)古同够”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彀"},{"id":"glyph-seal-5f52","script":"seal","character":"归","reading":"guī","description":"凡诸侯之女归宁曰来\n⒈回，返，回到～家团聚。～国华侨。回～祖国。〈引〉还给～还。物～原主。\n⒉趋向同～殊途。四海～心。\n⒊由，属于这件事～她办。\n⒋聚拢，并入～档。～并。颗粒～仓。\n⒌依附，附属～附。～属。\n⒍顺服，反正～顺。弃邪～正。\n⒎结局，结论～宿。～结。\n⒏除，珠算中一位数的除法三～。七～。\n归kuì 1.通\"馈\"。赠送。 2.通\"愧\"。惭愧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-归"},{"id":"glyph-seal-5f53","script":"seal","character":"当","reading":"dāng；dàng","description":"dàng：(1)合宜恰～。适～。妥～。\n(2)抵得上，等于一个人～俩人用。\n(3)姑且作为～做。长歌～哭。安步～车。\n(4)认为我～你已经回家了。\n(5)在同一时间～日。～年。～世。\n(6)吃亏，受骗上～。\n(7)抵押抵～。押～。典～（用实物作抵押向当铺借钱）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-当"},{"id":"glyph-seal-5f55","script":"seal","character":"录","reading":"lù","description":"记载言行事物的册籍\n次第,次序\n总领\n余之手录。\n⒈记载，登记～音。～功。\n⒉抄写抄～。摘～。\n⒊记载言行或事物的书刊、文本语～。回忆～。备忘～。\n⒋任用，采取～用。～取。收～。\n⒌审查并记载犯人的罪状～供。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-录"},{"id":"glyph-seal-5f57","script":"seal","character":"彗","reading":"huì","description":"huì：扫帚～星（俗称扫帚星”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彗"},{"id":"glyph-seal-5f58","script":"seal","character":"彘","reading":"zhì","description":"zhì：猪狗～不如。狗～不食。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彘"},{"id":"glyph-seal-5f5d","script":"seal","character":"彝","reading":"yí","description":"yí：(1)古代盛酒的器具，亦泛指古代宗庙常用的祭器～器。～鼎。～尊。\n(2)常理，法理～训（指长辈对后辈的日常训诲）。～伦。～常。～章。\n(3)中国少数民族，主要分布于四川省、云南省和贵川省～族。～人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彝"},{"id":"glyph-seal-5f62","script":"seal","character":"形","reading":"xíng","description":"xíng：(1)实体～仪（体态仪表）。～体。～貌。～容。～骸。～单影只。～影相吊。\n(2)样子～状。～式。～态。～迹。地～。情～。\n(3)表现～诸笔墨。喜～于色。\n(4)对照，比较相～见绌。\n(5)状况，地势～势。\n(6)古同型”，模子。\n(7)古同刑”，刑罚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-形"},{"id":"glyph-seal-5f64","script":"seal","character":"彤","reading":"tóng","description":"tóng：(1)红色～管（ａ．赤管笔，古代女史以此记事，后因用于女子文墨之事；ｂ．一说是红色管状的初生之草）。～云。～庭（中国汉代皇宫以朱红色漆中庭，后泛指皇宫）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彤"},{"id":"glyph-seal-5f66","script":"seal","character":"彦","reading":"yàn","description":"yàn：古代指有才学、德行的人俊～。～士。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彦"},{"id":"glyph-seal-5f67","script":"seal","character":"彧","reading":"yù","description":"yù：有文采～～（ａ．富有文采的样子，如羌瑰玮以壮丽，纷～～其难分”；ｂ．茂盛的样子，如黎稷～～”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彧"},{"id":"glyph-seal-5f69","script":"seal","character":"彩","reading":"cǎi","description":"cǎi：(1)各种颜色交织～云。～虹。～霞。～绘。～陶。～绸。～笔。～车。～蛋（ａ．画在鸡、鸭蛋壳上的工艺品；ｂ．方言，松花蛋）。～灯。五～缤纷。\n(2)五色的绸子剪～。\n(3)指赌博或某种竞赛中赢得的东西～金。～票。得～。\n(4)称赞、夸奖的欢呼声喝（hè）～。\n(5)花样，完美的成分丰富多～。文～。\n(6)喻战士受伤流的血挂～。～口。\n(7)指彩金～券。中（zhòng）～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彩"},{"id":"glyph-seal-5f6a","script":"seal","character":"彪","reading":"biāo","description":"biāo：(1)虎身上的斑纹，引申为有文采～炳。\n(2)小老虎。\n(3)身躯魁悟～悍。～壮。～形大汉。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彪"},{"id":"glyph-seal-5f6c","script":"seal","character":"彬","reading":"bīn","description":"bīn：〔～～〕形容文雅，如～～有礼”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彬"},{"id":"glyph-seal-5f6d","script":"seal","character":"彭","reading":"péng；bāng","description":"péng：姓。\nbāng：〔～～〕ａ．众多的样子，如行人～～”；ｂ．雄壮有力的样子，如四牡～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彭"},{"id":"glyph-seal-5f70","script":"seal","character":"彰","reading":"zhāng","description":"zhāng：(1)明显，显著～～。昭～。～明。欲盖弥～。\n(2)表明，显扬表～。～善瘅恶（表扬好的，憎恨坏的）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彰"},{"id":"glyph-seal-5f77","script":"seal","character":"彷","reading":"páng；fǎng","description":"páng：〔～徨〕犹疑不决，不知道往哪里走好。亦作旁皇”。\nfǎng：同仿”，仿佛。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彷"},{"id":"glyph-seal-5f79","script":"seal","character":"役","reading":"yì","description":"yì：(1)服兵务，从军从～。现～。\n(2)战事战～。\n(3)服劳力之事劳～。徭～。\n(4)使唤～使。奴～。\n(5)被役使的人～夫。～徒。仆～。杂～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-役"},{"id":"glyph-seal-5f7b","script":"seal","character":"彻","reading":"chè","description":"拆毁;拆下\n彻 chè通；透响～云霄、～夜不眠。\n【彻骨】渗进骨头里。形容程度极深。\n【彻头彻尾】从头到尾；完全彻底。\n⒉〈古〉通\"撤\"～退。～去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彻"},{"id":"glyph-seal-5f7c","script":"seal","character":"彼","reading":"bǐ","description":"bǐ：(1)那，那个～岸。此起～伏。\n(2)他，对方知己知～。～此。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彼"},{"id":"glyph-seal-5f80","script":"seal","character":"往","reading":"wǎng","description":"wǎng：(1)去，到～返。～复。～还（huán）。～来。交～。向～。勇～直前。\n(2)过去～昔。～日。～事。～古。～常。以～。一如既～。\n(3)同望”⑤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-往"},{"id":"glyph-seal-5f81","script":"seal","character":"征","reading":"zhēng","description":"⒉讨伐，用武力制服～讨。～服。南～北战。\n⒊争夺，夺取力～。\n⒋召集，收用～召。～集。～收。～用。～税。～调。～兵。\n⒌找请，寻求～聘。～求。～文。～询意见。\n⒍证明，证验有～。实物可～。\n⒎现象，迹象～象。～兆。特～。\n征chéng 1.通\"惩\"。警戒;惩罚。 2.古地名。在今陕西省澄城县。\n征zhǐ 1.古五音之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-征"},{"id":"glyph-seal-5f82","script":"seal","character":"徂","reading":"cú","description":"cú：(1)往自西～东。\n(2)过去，逝岁月其～。\n(3)开始六月～署。\n(4)古同殂”，死亡。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徂"},{"id":"glyph-seal-5f84","script":"seal","character":"径","reading":"jìng","description":"经过,行经\n南北为径\n夫惟捷径以窘步。\n⒈小路山～。曲～。〈引〉取道，经过夜～泽中。〈喻〉达到目的之方法找门～。取捷～。\n⒉直往，直接，直截了当～往。～自去。～向对方联系。\n⒊［直径］两端以圆周为界，经过圆心的直线。又称直径的长度井口～三尺。\n⒋［半径］圆心到圆周的直线。\n径jīng 1.经过;行经。 2.南北为径。参见\"径轮\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-径"},{"id":"glyph-seal-5f85","script":"seal","character":"待","reading":"dài；dāi","description":"dài：(1)等，等候～到。～旦。拭目以～。\n(2)以某种态度或行为加之于人或事物对～。招～。～遇。～人接物。\n(3)将，要（古典戏曲小说和现代某些方言的用法）正～出门，有人来了。\ndāi：停留，逗留，迟延你～一会儿再走。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-待"},{"id":"glyph-seal-5f88","script":"seal","character":"很","reading":"hěn","description":"hěn：(1)甚，非常，表示程度加深～快。～好。\n(2)古同狠”，凶恶。\n(3)古代指争讼～无求胜”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-很"},{"id":"glyph-seal-5f8b","script":"seal","character":"律","reading":"lǜ；lv","description":"lǜ：(1)法则，规章纪～。法～。定～。规～。清规戒～。～师。\n(2)约束～己。\n(3)中国古代审定乐音高低的标准，把声音分为六律（阳律）和六品（阴律）∠称十二律”～吕（古代用竹管制成的校正乐律的器具，以管的长短来确定音的不同高度，从低音管算起，成奇数的六个管称律”；成偶数的六个管称吕”，后来律吕”作为音律的统称）。\n(4)旧诗的一种体裁～诗。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-律"},{"id":"glyph-seal-5f90","script":"seal","character":"徐","reading":"xú","description":"xú：(1)缓，慢慢地～步。～缓。～图。～～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徐"},{"id":"glyph-seal-5f92","script":"seal","character":"徒","reading":"tú","description":"tú：(1)步行～步。～涉。\n(2)空～手。\n(3)白白地～然。～劳无益。\n(4)只；仅仅家～四壁。\n(5)从事学习的人～弟。～工。学～。师～。\n(6)同一派系或信仰同一宗教的人信～。教～。党～。\n(7)人（多指坏人）匪～。暴～。赌～。叛～。\n(8)剥夺犯人自由的刑法～刑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徒"},{"id":"glyph-seal-5f97","script":"seal","character":"得","reading":"dé；děi；de","description":"dé：得到、获得；适合。děi：需要，必须。de：助词，连接动作与补语，如写得好。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5f99","script":"seal","character":"徙","reading":"xǐ","description":"xǐ：(1)迁移～居（搬家）。迁～。流～。\n(2)古代称流放的刑罚～边（流放有罪的人到边远地区）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徙"},{"id":"glyph-seal-5fa1","script":"seal","character":"御","reading":"yù","description":"后亦泛指驾驭一切运行或飞行之物\n御轻舟而上溯,\n⒈驾驭车马～车。又指驾驭车马的人～手。\n⒊称与皇帝有关的～衣。～旨。～用。～河桥。\n⒋侍奉，敬献～于君。～欲王公。\n⒌抵挡，阻止～敌。抵～。～风寒。\n御yà 1.迎接。 2.向;面向。 3.逢迎;迎合。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-御"},{"id":"glyph-seal-5faa","script":"seal","character":"循","reading":"xún","description":"xún：(1)遵守，依照沿袭遵～。因～。～环。～规蹈矩。\n(2)古同巡”，巡行。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-循"},{"id":"glyph-seal-5fad","script":"seal","character":"徭","reading":"yáo","description":"yáo：古代统治者强制人民承担的无偿劳动～役。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徭"},{"id":"glyph-seal-5fae","script":"seal","character":"微","reading":"wēi","description":"wēi：(1)小，细小细～。轻～。～小。～型。～观。～雕。～积分。～电脑。～量元素。谨小慎～。～乎其～。\n(2)少；稍稍～。～笑。～调（tiáo）。\n(3)衰落；低下卑～。～贱。\n(4)精深；精妙～妙。精～。～言大义。\n(5)隐约；不明～茫。～词（隐晦的批评）。\n(6)隐匿白公奔山而缢，其徒～亡”。\n(7)暗中察访～行。\n(8)无，非～斯人，吾谁与归”。\n(9)与某一物理量的单位连用时，表示该量的百万分之一～米（公制长度单位，米”的百万分之一）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-微"},{"id":"glyph-seal-5fb5","script":"seal","character":"徵","reading":"zhǐ；zhēng","description":"zhǐ：古代五音“宫、商、角、徵、羽”之一。zhēng：古同“征”，有征召、征验等义。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5fb7","script":"seal","character":"德","reading":"dé","description":"dé：(1)人们共同生活及行为的准则和规范，品行，品质美～。品～。公～。～行。道～。～性。～育（以一定的社会要求，进行思想的、政治的和道德的教育）。～才兼备。度～量力。～高望重。\n(2)心意，信念一心一～。\n(3)恩惠～施。～泽（德化和恩惠）。～惠。感恩戴～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-德"},{"id":"glyph-seal-5fbc","script":"seal","character":"徼","reading":"jiǎo；jiào","description":"jiǎo：(1)同侥”。\n(2)求。\njiào：(1)边界～外。\n(2)巡逻，巡察～巡。～道（巡查警戒的道路）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徼"},{"id":"glyph-seal-5fbd","script":"seal","character":"徽","reading":"huī","description":"huī：(1)标志，符号国～。校～。帽～。～章。～记。～帜（zhì）。\n(2)美好的～号。\n(3)系琴弦的绳，后用做抚琴标记的名称，古琴全弦共十三徽。\n〔～州〕旧地名，在今中国安徽省歙县。简称徽”，如～墨”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徽"},{"id":"glyph-seal-5fc3","script":"seal","character":"心","reading":"xīn","description":"xīn：(1)人和高等动物体内主管血液循环的器官（通称心脏”）～包。～律。～衰。～悸。\n(2)中央，枢纽，主要的～腹。中～。\n(3)习惯上指思想的器官和思想情况，感情等～理。～曲。～魄。～地。～扉。衷～。～旷神怡。人～惟危。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-心"},{"id":"glyph-seal-5fc5","script":"seal","character":"必","reading":"bì","description":"bì：(1)一定～定。～然。～须（一定要）。～需（不可少的）。势～。未～。事～躬亲。\n(2)决定，肯定深念远虑兮，胜乃可～”。\n(3)固执毋意，毋～”。\n(4)果真，假使王～无人，臣愿奉璧往使”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-必"},{"id":"glyph-seal-5fcc","script":"seal","character":"忌","reading":"jì","description":"jì：(1)嫉妒，憎恨猜～。～才。～能。～妒。～贤妒能。\n(2)害怕，畏惧顾～。肆无～惮。\n(3)禁戒～戒。～食。～讳。禁～。\n(4)父母或祖先死亡的日子，迷信称不吉利的日子～日。～辰。生～（已死父母的生日）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忌"},{"id":"glyph-seal-5fcd","script":"seal","character":"忍","reading":"rěn","description":"rěn：(1)耐，把感情按住不让表现～耐。～痛。～受。容～。～俊不禁（忍不住笑）。\n(2)狠心，残酷～心。残～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忍"},{"id":"glyph-seal-5fd2","script":"seal","character":"忒","reading":"tuī；tè","description":"tè：差错差～。\ntuī：太风～大。这人～坏。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忒"},{"id":"glyph-seal-5fd6","script":"seal","character":"忖","reading":"cǔn","description":"cǔn：揣度（duó），思量～度（duó）。～量（liàng）。思～。自～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忖"},{"id":"glyph-seal-5fd7","script":"seal","character":"志","reading":"zhì","description":"zhì：(1)意向～愿。～气。～趣（志向和兴趣）。～士（有坚决意志和高尚节操的人）。～学。\n(2)记，记在心里～喜。～哀。永～不忘。\n(3)记号标～。\n(4)记载的文字杂～。～怪（记载怪异的事）。\n(5)称轻重，量长短、多少～子。用碗～～。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-志"},{"id":"glyph-seal-5fd8","script":"seal","character":"忘","reading":"wàng","description":"wàng：不记得，遗漏～记。～却。～怀。～我。～情。～乎所以。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忘"},{"id":"glyph-seal-5fdd","script":"seal","character":"忝","reading":"tiǎn","description":"tiǎn：辱，有愧于，常用作谦辞～在知交。～属知己。～列门墙（愧在师门）。～为人师。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忝"},{"id":"glyph-seal-5fe0","script":"seal","character":"忠","reading":"zhōng","description":"zhōng：诚心尽力～心。～诚。～实。～告。～于。～魂。～义。～贞。效～。赤胆～心。～言逆耳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忠"},{"id":"glyph-seal-5fe1","script":"seal","character":"忡","reading":"chōng","description":"chōng：〔～～〕忧虑不安的样子，如忧心～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忡"},{"id":"glyph-seal-5fe4","script":"seal","character":"忤","reading":"wǔ","description":"wǔ：逆，不顺从～耳（逆耳）。～逆（ａ．背犯，违反；ｂ．不孝顺父母）。～视（逆视、抗视、正视相看）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忤"},{"id":"glyph-seal-5fe7","script":"seal","character":"忧","reading":"yōu","description":"忧其民。\n⒈发愁，担心～愁。担～。～心如焚。\n⒉可忧愁的事～患。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忧"},{"id":"glyph-seal-5feb","script":"seal","character":"快","reading":"kuài","description":"kuài：(1)速度大，与慢”相对～车。～件。～步。～速。～捷。～马加鞭。\n(2)赶紧，从速赶～。\n(3)将，就要；接近天～亮了。\n(4)灵敏他脑子真～。眼明手～。\n(5)锐利，锋利，与钝”相对王麻子刀剪真～。\n(6)爽利，直截了当爽～。心直口～。～人～语。\n(7)高兴舒服～乐。～意。痛～。愉～。～感。～事。～慰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-快"},{"id":"glyph-seal-5ff1","script":"seal","character":"忱","reading":"chén","description":"chén：(1)真诚的情意热～。\n(2)诚恳～挚。～辞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忱"},{"id":"glyph-seal-5ff5","script":"seal","character":"念","reading":"niàn","description":"niàn：(1)惦记，常常想惦～。怀～。～头（思想、想法）。悼～。～旧。～物。\n(2)心中的打算，想法，看法意～。杂～。信～。\n(3)说，读，诵读～白（戏剧道白）。～叨。～经。～书。\n(4)廿”的大写。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-念"},{"id":"glyph-seal-5ffb","script":"seal","character":"忻","reading":"xīn","description":"xīn：(1)同欣”。\n(2)开导，启发善者～民之善，闭民之恶”。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忻"},{"id":"glyph-seal-5ffd","script":"seal","character":"忽","reading":"hū","description":"hū：(1)粗心，不注意～视。疏～。～略。玩～职守。\n(2)迅速，突然～而。～然。～地。～高～低。\n(3)长度和重量单位（十忽为一丝，十丝为一毫）～微（极言细微）。微～其微。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忽"},{"id":"glyph-seal-5ffe","script":"seal","character":"忾","reading":"kài","description":"愤恨,愤怒\n忾xì 1.叹息。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忾"},{"id":"glyph-seal-5fff","script":"seal","character":"忿","reading":"fèn","description":"fèn：生气，恨～恨。～怒。～詈（因愤怒而骂）。不～（不服气，不平）。气不～（看到不平的事，心中不服气）。～～不平。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忿"},{"id":"glyph-seal-6000","script":"seal","character":"怀","reading":"huái","description":"维以不永怀。\n心里存有;怀藏\n⒈胸前抱在～里。\n⒉想念～念故乡。～旧友。\n⒊心意，胸怀正中下～。襟～坦白。\n⒋揣着，包藏～抱。～疑。～恨。～怒未发。\n⒌怀胎母之～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怀"},{"id":"glyph-seal-6001","script":"seal","character":"态","reading":"tài","description":"⒈形状，样子形～。体～。状～。常～。姿～。\n⒉情况事～。\n①说话与举止的神情～度自然。\n②对人对事所采取的立场或看法～度傲慢。表明～度。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-态"},{"id":"glyph-seal-6002","script":"seal","character":"怂","reading":"sǒng","description":"怂恿\n⒈惊恐。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怂"},{"id":"glyph-seal-6003","script":"seal","character":"怃","reading":"wǔ","description":"哀怜\n怅然失意的样子\n惊愕的样子\n通妩”。媚好的样子\n⒈茫然失意的样子～然。\n⒉惊愕。\n怃hū 1.傲慢。参见\"怃敖\"。 2.通\"幠\"。大;粗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怃"},{"id":"glyph-seal-6005","script":"seal","character":"怅","reading":"chàng","description":"怅 chàng失意；不称心；不痛快；惆～。\n【怅然若失】不如意，仿佛丢了什么似的。\n【怅惘】惆怅迷惘；心事重重，无精打采。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怅"},{"id":"glyph-seal-6006","script":"seal","character":"怆","reading":"chuàng","description":"匆遽,慌乱\n怆然\n怆然泪下\n怆痛\n怆痛不已\n怆 chuàng悲伤。\n【怆然】伤悲的样子～泪下。\n怆chuǎng 1.失意貌。参见\"怆恍\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怆"},{"id":"glyph-seal-600d","script":"seal","character":"怍","reading":"zuò；zhà","description":"zuò：(1)惭愧渐～。愧～。仰不愧于天，俯不～于人。\n(2)（脸色）改变将即席，容毋～。”\nzhà：〔??（yà）～〕心多奸诈。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怍"},{"id":"glyph-seal-600f","script":"seal","character":"怏","reading":"yàng","description":"yàng：(1)不服气，不满意～～不乐（形容不满意的神情）。～然不悦（形容不高兴的样子）。\n(2)自大～然自足。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怏"},{"id":"glyph-seal-6012","script":"seal","character":"怒","reading":"nù","description":"nù：(1)生气，气愤～色。～视。～叱。～骂。恼～。息～。\n(2)气势盛～涛。～火。心花～放。\n(3)中国少数民族，主要分布于云南省～族。\n(4)谴责若不可教而后～之”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怒"},{"id":"glyph-seal-6015","script":"seal","character":"怕","reading":"pà","description":"pà：(1)恐惧～人。～死ˇ～。惧～。可～。\n(2)或许，表示疑虑或猜想恐～他别有用意。～是。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怕"},{"id":"glyph-seal-6016","script":"seal","character":"怖","reading":"bù","description":"bù：惧怕～栗。～惧。恐～。情景可～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怖"},{"id":"glyph-seal-6019","script":"seal","character":"怙","reading":"hù","description":"hù：依靠，仗恃～势。～恃（亦为父母的代称）。～乱（乘祸乱之际谋取私利）。～恶不悛（坚持作恶，不肯悔改）。失～（失了父亲）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怙"},{"id":"glyph-seal-601b","script":"seal","character":"怛","reading":"dá","description":"dá：(1)忧伤，悲苦～～（忧伤不安）。～伤。～忧。惨～。\n(2)惊惧。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怛"},{"id":"glyph-seal-601c","script":"seal","character":"怜","reading":"lián","description":"爱,惜\n⒈同情～惜。～悯。\n⒉爱惜～爱。\n①可爱百花高楼更可～。\n②值得同情可～身上衣正单。\n怜líng 1.见\"怜悧\"﹑\"怜牙悧齿\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怜"},{"id":"glyph-seal-601d","script":"seal","character":"思","reading":"sī；sāi","description":"sī：(1)想，考虑，动脑筋～想（ａ．客观存在反映在人的意识中经过思维活动而产生的结果；ｂ．想法，念头；ｃ．思量）。～忖。～索。～维。沉～。寻～。见异～迁。\n(2)想念，挂念～念。～恋。相～。\n(3)想法～绪。～致（新颖独到的构思、意趣）。构～。\n(4)姓。\n念；想；\nsāi：〔于～〕多胡须的样子，如自捋颔下，则～～者如故矣”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-思"},{"id":"glyph-seal-6020","script":"seal","character":"怠","reading":"dài","description":"dài：(1)懒惰，忪懈～惰。～倦。～工。懈～。\n(2)轻慢，不尊敬～傲。～慢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怠"},{"id":"glyph-seal-6021","script":"seal","character":"怡","reading":"yí","description":"yí：和悦，愉快～色（容色和悦）。～声（语声和悦）。～和。～乐（lè）。～神。～悦。～目（快意于所见，悦目）。心旷神～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怡"},{"id":"glyph-seal-6025","script":"seal","character":"急","reading":"jí","description":"jí：(1)焦燥～燥。着～。焦～。\n(2)气恼，发怒～眼。\n(3)使着急这件事真～人。\n(4)匆促～促。～功近利（急于求目前的成效和利益）。\n(5)迅速，又快又猛～流。～进。～先锋。～风暴雨。\n(6)迫切，要紧～切。～诊。～事。\n(7)严重告～。\n(8)对大家的事情或别人的困难尽快帮助～人之难。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-急"},{"id":"glyph-seal-6027","script":"seal","character":"性","reading":"xìng","description":"xìng：(1)人或事物的本身所具有的能力、作用等～质。～格。～命（生命）。～能。个～。属～。\n(2)性质，思想、感情等方面的表现典型～。开放～。指令～。\n(3)男女或雌雄的特质～别。男～。女～。\n(4)有关生物生殖的～交。～欲。～爱。～感。～解放。\n(5)表示名词（以及代词、形容词）的类别的语法范畴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-性"},{"id":"glyph-seal-6028","script":"seal","character":"怨","reading":"yuàn","description":"yuàn：(1)仇恨～恨。恩～。宿～。～仇。～敌。～府（大家怨恨的对象）。～声载道。\n(2)不满意，责备埋（mán）～。抱～。～言。任劳任～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怨"},{"id":"glyph-seal-6029","script":"seal","character":"怩","reading":"ní","description":"ní：〔忸～〕见忸”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怩"},{"id":"glyph-seal-602a","script":"seal","character":"怪","reading":"guài","description":"guài：(1)奇异，不平常～诞（离奇古怪）。～事。～物。～讶。～圈（quān）。～话。～异。奇形～状。\n(2)惊奇大惊小～。～不得。\n(3)传说中的妖魔之类鬼～。妖～。\n(4)性情乖僻或行为异样的人～癖（古怪的癖好）。～僻（古怪）。\n(5)很，非常～好的天气。\n(6)怨，责备不～你。～罪。～怨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怪"},{"id":"glyph-seal-602b","script":"seal","character":"怫","reading":"fú","description":"fú：忿怒的样子～郁（ａ．愤懑；ｂ．心情不舒畅）。～然作色。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怫"},{"id":"glyph-seal-602f","script":"seal","character":"怯","reading":"qiè","description":"qiè：(1)胆小，没勇气～场。～懦。～弱。～步。～阵。羞～。\n(2)俗气，见识不广，不合时宜露～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怯"},{"id":"glyph-seal-6035","script":"seal","character":"怵","reading":"chù","description":"chù：恐惧～惕（恐惧警惕）。～惧。～头。发～。～目惊心。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怵"},{"id":"glyph-seal-603b","script":"seal","character":"总","reading":"zǒng","description":"聚合;汇集\n无总\n⒈全，全部，主要的，为首的～的。～纲。～则。～统。～指挥。～司令。\n⒉聚合，汇集～括。～共。～计。\n⒊一直，经常她～爱笑。他～是吃苦在前。\n⒋一定，毕竟～会胜利。这件事～要办理。\n⒌统领～兵西下。\n①终究，终于～算成功了。\n②勉强，还可以这孩子能做到这样，～算不错了。\n总zōng 1.丝数名。古以丝八十根为\"总\"。\n总cōng 1.通\"纒\"。绢的一种。 2.通\"恠\"。参见\"总至\"。 3.通\"葱\"。参见\"总极\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-总"},{"id":"glyph-seal-603c","script":"seal","character":"怼","reading":"duì","description":"凶狠\n怼duì 1.怨恨。 2.凶狠。 3.见\"?怼\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怼"},{"id":"glyph-seal-603f","script":"seal","character":"怿","reading":"yì","description":"悦服\n更改\n怿,改也。自山而东,或曰悛,或曰怿","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怿"},{"id":"glyph-seal-6041","script":"seal","character":"恁","reading":"nín；nèn","description":"nèn：(1)那么，那样，如此，这样～大。～高。\n(2)那～时节。\n(3)怎么却～地教甚么人在间壁吱吱地哭，搅掩兄弟们吃酒？”\n(4)恩，念宜亦勤～旅力，以充厥道”。\nnín：古同您”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恁"},{"id":"glyph-seal-6042","script":"seal","character":"恂","reading":"xún","description":"xún：(1)相信且～士师之言可也”。\n(2)畅通～达。\n(3)恐惧，惶急～惧。\n〔～～〕ａ．担心的样子，如吾～～而起，视其缶”；ｂ．谦恭谨慎的样子，如孔子于乡党，～～如也，似不能言者”；ｃ．同循循”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恂"},{"id":"glyph-seal-6043","script":"seal","character":"恃","reading":"shì","description":"恃shì依靠，依赖，倚仗有～无恐。～才傲物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恃"},{"id":"glyph-seal-604d","script":"seal","character":"恍","reading":"huǎng","description":"huǎng：(1)忽然～然大悟。\n(2)仿佛～如隔世。～惚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恍"},{"id":"glyph-seal-6050","script":"seal","character":"恐","reading":"kǒng","description":"kǒng：(1)害怕，畏惧～惧。～怖。～慌。惊～。有恃无～。\n(2)恫吓（hè）～吓（hè）。\n(3)疑虑～怕。～不能成功。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恐"},{"id":"glyph-seal-6052","script":"seal","character":"恒","reading":"héng","description":"héng：(1)持久～心。～久。～定。～齿。永～。～星。～温。\n(2)经常的，普通的～言。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恒"},{"id":"glyph-seal-6055","script":"seal","character":"恕","reading":"shù","description":"shù：(1)原谅，宽容～宥。～谅。～罪。宽～。饶～。～我直言。\n(2)以自己的心推想别人的心～道。忠～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恕"},{"id":"glyph-seal-6059","script":"seal","character":"恙","reading":"yàng","description":"yàng：(1)膊然无～。偶染微～。别来无～。\n(2)忧何～不已”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恙"},{"id":"glyph-seal-605a","script":"seal","character":"恚","reading":"huì","description":"huì：恨，怒～恨。～怒。～望。～愤。怒～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恚"},{"id":"glyph-seal-6062","script":"seal","character":"恢","reading":"huī","description":"huī：弘大，发扬～张。～弘。～廓。\n〔～复〕变成原来的样子，如健康已经～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恢"},{"id":"glyph-seal-6063","script":"seal","character":"恣","reading":"zì；zī","description":"zī：(1)放纵，无拘束～意。～肆。～睢。～情。～行无忌。\n(2)方言，舒服透～。睡得真～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恣"},{"id":"glyph-seal-6064","script":"seal","character":"恤","reading":"xù","description":"xù：(1)对别人表同情，怜悯～刑（施刑慎重，不严刑以逼供）。体～。\n(2)救济～金。抚～。\n(3)忧虑～～（忧虑的样子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恤"},{"id":"glyph-seal-6068","script":"seal","character":"恨","reading":"hèn","description":"hèn：(1)怨，仇视怨～。愤～。仇～。痛～。\n(2)为做不到或做不好而内心不安～事。悔～。遗～。抱～终天。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恨"},{"id":"glyph-seal-6069","script":"seal","character":"恩","reading":"ēn","description":"ēn：好处，深厚的情谊～爱。～赐。～宠（指帝王对臣下的优遇和宠幸）。～德。～典。～惠。～仇。感～。开～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恩"},{"id":"glyph-seal-606b","script":"seal","character":"恫","reading":"dòng","description":"dòng：〔～吓（hè）〕恐吓，吓（xià）唬。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恫"},{"id":"glyph-seal-606c","script":"seal","character":"恬","reading":"tián","description":"tián：安静，安然，坦然～静。～适。～然。～谧。～淡（淡泊名利，清静无为）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恬"},{"id":"glyph-seal-606d","script":"seal","character":"恭","reading":"gōng","description":"gōng：肃敬，谦逊有礼貌～敬。～谨。～候。～维。～贺。打～（拱揖）。洗耳～听。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恭"},{"id":"glyph-seal-606f","script":"seal","character":"息","reading":"xī","description":"xī：(1)呼吸时进出的气鼻～。喘～。叹～。窒～。瞬～万变。\n(2)停止，歇休～。歇～。～怒。～兵。～事宁人。～止。平～。偃旗～鼓。\n(3)繁殖，滋生休养生～。滋～。\n(4)音信消～。信～。\n(5)儿女子～。\n(6)利钱～率（lǜ）。利～。月～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-息"},{"id":"glyph-seal-6070","script":"seal","character":"恰","reading":"qià","description":"qià：(1)正巧，刚刚～巧。～好。～～（ａ．刚好，如～～相反”；ｂ．融和，如春光～～”；ｃ．鸟鸣声，如自在娇莺～～啼”）。～似。\n(2)合适，适当～当。～切（qiè）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恰"},{"id":"glyph-seal-6076","script":"seal","character":"恶","reading":"è；wù；wū","description":"è：(1)不好～感。～果。～劣。～名。丑～。\n(2)凶狠～霸。～棍。险～。凶～。\n(3)犯罪的事，极坏的行为～贯满盈。\n好；美；爱；善；\nwù：讨厌，憎恨，与好（hào）”相对可～。厌～∶（hào）～。\n好；美；爱；善；\n（噁）\ně：〔～心〕要呕吐的感觉；亦指对人和事的厌恶态度。\n好；美；爱；善；\nwū：(1)古同乌”，疑问词，哪，何。\n(2)文言叹词，表示惊讶～，是何言也！","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恶"},{"id":"glyph-seal-6078","script":"seal","character":"恸","reading":"tòng","description":"极其悲痛\n恸哭\n听见青年和老人抽泣和恸哭","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恸"},{"id":"glyph-seal-607a","script":"seal","character":"恺","reading":"kǎi","description":"假借为凯”。军队胜利后所奏之乐\n⒈欢乐，和乐大～。\n⒊〈古〉通\"凯\"奏～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恺"},{"id":"glyph-seal-607b","script":"seal","character":"恻","reading":"cè","description":"恳切\n恻 cè哀痛；悲伤凄～、～隐之心。\n【恻隐之心】对受苦难的人表示同情的心意。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恻"},{"id":"glyph-seal-607d","script":"seal","character":"恽","reading":"yùn","description":"敦厚\n恽yùn姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恽"},{"id":"glyph-seal-607f","script":"seal","character":"恿","reading":"yǒng","description":"见怂恿”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恿"},{"id":"glyph-seal-6084","script":"seal","character":"悄","reading":"qiāo；qiǎo","description":"qiǎo：(1)忧愁～切。～怆。～然落泪。忧心～～。\n(2)寂静无声～然无声。～寂。～静。～声。\nqiāo：没有声音或声音很低，不让人知道深夜静～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悄"},{"id":"glyph-seal-6089","script":"seal","character":"悉","reading":"xī","description":"xī：(1)知道洞～（很清楚地知道）。尽～。获～。来函敬～。\n(2)尽，全～力。～心。～数（shù）。～数（shǔ）（完全列举，如不可～～”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悉"},{"id":"glyph-seal-608c","script":"seal","character":"悌","reading":"tì","description":"tì：敬爱哥哥，引申为顺从长（zhǎng）上孝～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悌"},{"id":"glyph-seal-608d","script":"seal","character":"悍","reading":"hàn","description":"hàn：(1)勇猛，勇敢强～。精～。～勇。\n(2)凶暴～然。凶～。～吏。～戾。\n(3)强劲，急暴湍～。急～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悍"},{"id":"glyph-seal-6092","script":"seal","character":"悒","reading":"yì","description":"yì：忧愁，不安忧～。郁～。～怏。～愤。～闷。～～不乐。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悒"},{"id":"glyph-seal-6094","script":"seal","character":"悔","reading":"huǐ","description":"huǐ：懊恼过去做得不对后～。懊～。～改。～恨。～悟。追～莫及。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悔"},{"id":"glyph-seal-6096","script":"seal","character":"悖","reading":"bèi","description":"bèi：(1)混乱，相冲突～乱。～逆。～异。～论。并行不～。\n(2)惑，违背道理，谬误～谬。～惑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悖"},{"id":"glyph-seal-609b","script":"seal","character":"悛","reading":"quān","description":"quān：悔改～心。～改。～革（悔改）。～容（悔改的表情）。怙恶不～（坚持作恶，不肯悔改）。过而不～，亡之本也。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悛"},{"id":"glyph-seal-609d","script":"seal","character":"悝","reading":"kuī；lǐ","description":"kuī：嘲笑，诙谐～穆公于宫室”。\nlǐ：忧愁云如何～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悝"},{"id":"glyph-seal-609f","script":"seal","character":"悟","reading":"wù","description":"wù：理解，明白，觉醒醒～。领～。参（cān）～。感～。觉～。大彻大～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悟"},{"id":"glyph-seal-60a0","script":"seal","character":"悠","reading":"yōu","description":"yōu：(1)久，远，长～久。～远。～扬。\n(2)在空中摆动～荡。晃～。转～。\n(3)稳住，控制～着点劲。\n(4)闲适，闲散～闲。～然。～忽（形容悠闲懒散）。～缓。～～（ａ．闲适，自由自在，如白云～～”；ｂ．忧郁，如～～我思”；ｃ．长久，遥远，如～～长夜”；ｄ．众多；ｅ．荒谬，如～～之谈”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悠"},{"id":"glyph-seal-60a3","script":"seal","character":"患","reading":"huàn","description":"huàn：(1)忧虑～得～失。忧～。\n(2)灾祸～难。祸～。隐～。防～未然。\n(3)害病～病。～者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-患"},{"id":"glyph-seal-60ab","script":"seal","character":"悫","reading":"què","description":"恭谨\n厚道;朴实","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悫"},{"id":"glyph-seal-60b1","script":"seal","character":"悱","reading":"fěi","description":"fěi：想说可是不能够恰当地说出来～愤（忧思蓄积）。～恻。不～不发。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悱"},{"id":"glyph-seal-60b2","script":"seal","character":"悲","reading":"bēi","description":"bēi：(1)伤心，哀痛～哀。～伤。～怆。～痛。～切。～惨。～凉。～愤。～凄。～恸。～吟。～壮。～观。～剧。乐极生～。\n(2)怜悯～天悯人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悲"},{"id":"glyph-seal-60b4","script":"seal","character":"悴","reading":"cuì","description":"cuì：(1)忧伤人力雕残，百姓愁～”。\n(2)衰弱，疲萎憔～。～容。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悴"},{"id":"glyph-seal-60b8","script":"seal","character":"悸","reading":"jì","description":"jì：因害怕而自觉心跳惊～。～栗（心惊肉跳）。～动。心有余～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悸"},{"id":"glyph-seal-60bc","script":"seal","character":"悼","reading":"dào","description":"dào：悲伤，哀念哀～。追～。～念。～亡。～唁。～词。～惜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悼"},{"id":"glyph-seal-60c5","script":"seal","character":"情","reading":"qíng","description":"qíng：(1)外界事物所引起的喜、怒、爱、憎、哀、惧等心理状态感～。～绪。～怀。～操。～谊。～义。～致。～趣。～韵。性～。～愫（真情实意）。～投意合。～景交融。\n(2)专指男女相爱的心理状态及有关的事物爱～。～人。～书。～侣。～诗。殉～。～窦初开（形容少女初懂爱情）。\n(3)对异性的欲望，性欲～欲。发～期。\n(4)私意～面。说～。\n(5)状况实～。事～。国～。～形。～势。～节。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-情"},{"id":"glyph-seal-60c6","script":"seal","character":"惆","reading":"chóu","description":"chóu：〔～怅〕失意，伤感。\n〔～惋〕悲叹，惋惜。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惆"},{"id":"glyph-seal-60c7","script":"seal","character":"惇","reading":"dūn","description":"dūn：(1)敦厚～厚。～朴。～谨。\n(2)劝勉，勤勉～诲（殷勤劝导）。～学。\n(3)推崇，尊重～信明义。～任仁人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惇"},{"id":"glyph-seal-60ca","script":"seal","character":"惊","reading":"jīng","description":"惊动;震惊\n⒈骡、马等因受吓而发狂乱奔控制～马。〈引〉害怕，精神紧张～骇。～慌失措。～心动魄。～恐万状。\n⒉意料以外的感觉～喜交集。倍感～奇。\n⒊扰乱，震动～扰。～动。～天动地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惊"},{"id":"glyph-seal-60d1","script":"seal","character":"惑","reading":"huò","description":"huò：(1)心疑不定，不明白对还是不对疑～。困～。惶～。智者不～。\n(2)使迷乱迷～。～乱。～人耳目。蛊～人心。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惑"},{"id":"glyph-seal-60d5","script":"seal","character":"惕","reading":"tì","description":"tì：(1)戒惧，小心谨慎警～。～惧。～～。～厉（心怀戒惧。亦作惕砺”）。\n(2)疾速一日～，一日留”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惕"},{"id":"glyph-seal-60dc","script":"seal","character":"惜","reading":"xī","description":"xī：(1)爱，重视爱～。顾～。怜～。珍～。\n(2)舍不得吝～。～别。～力。～指失掌（喻因小失大）。～墨如金。\n(3)感到遗憾，哀痛可～。～悯。惋～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惜"},{"id":"glyph-seal-60df","script":"seal","character":"惟","reading":"wéi","description":"wéi：(1)单，只～独。～一。～有。～恐。～命是从。～我独尊。\n(2)但是雨虽止，～路仍甚泥泞。\n(3)文言助词，常用于句首～妙～肖。～二月既望。\n(4)想，思考思～（亦作思维”）。～度（duó）（思量，揣度）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惟"},{"id":"glyph-seal-60e0","script":"seal","character":"惠","reading":"huì","description":"huì：(1)恩，好处恩～。～泽。～和。～爱。～握（恩惠深厚）。仁～。实～。施～于人。\n(2)给人财物或好处～政。互～互利。～及远人。～而不费（给人好处自己又没有什么耗费；常用以形容有实利而不多费钱财）。\n(3)敬辞，用于对方对待自己的行动～赠。～临。～顾。～存。～允。\n(4)古同慧”，聪明。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惠"},{"id":"glyph-seal-60e7","script":"seal","character":"惧","reading":"jù","description":"害怕，恐惧，如畏惧、惧怕。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-60e8","script":"seal","character":"惨","reading":"cǎn","description":"悲痛;伤心\n①悲惨；凄惨～状。\n②程度严重～败。\n③凶恶；狠毒～无人道。\n【惨不忍睹】悲惨得令人看不下去。睹看见。\n【惨怛】悲哀伤心的样子。\n【惨淡经营】费尽苦心从事某种工作或事业。惨淡境况困难或苦思极虑。经营规划从事。\n【惨景】悲惨的情形。\n【惨境】悲惨的境地。\n【惨剧】惨痛的事件。\n【惨无人道】残忍凶恶得连一点人性都没有。形容凶恶狠毒到了极点。\n【惨笑】内心痛苦、烦恼而勉强作出笑容。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惨"},{"id":"glyph-seal-60e9","script":"seal","character":"惩","reading":"chéng","description":"处罚\n改定\n克制;制止\n①处罚～处。\n②警戒～前毖后。\n【惩恶劝善】惩罚坏人，奖励好人。\n【惩戒】通过惩罚来达到警戒的目的。\n【惩前毖后】以过去的教训为警戒，谨防以后重犯错误。毖使谨慎。\n⒈警戒～前毖后。\n⒉责罚，处罚～罚。～办。严～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惩"},{"id":"glyph-seal-60ee","script":"seal","character":"惮","reading":"dàn","description":"使惊恐\n憎恶;忌恨\n权内\n惮 dàn怕肆无忌～。\n惮dá 1.惊骇。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惮"}];
